            {"label": "5-year impairment trend", "value": "2020-21 c. £1M → 2021-22 c. £1M → 2022-23 c. £2M → 2023-24 c. £2M → 2024-25 £2.54M (steady mental-health profile)"},
            {"label": "Estate gross floor area revalued", "value": "c. 65,000 m² across Leeds + York mental-health sites"},
            {"label": "MEA-DRC vs market value driver", "value": "Listed and heritage fabric (Bootham legacy + parts of Mount) below modernisation cost; secure-perimeter standards drive Newsam revaluation"},
            {"label": "RAAC scope", "value": "Not on HSSIB confirmed-RAAC list"},
            {"label": "NHP cohort + Reset Jan 2025 status", "value": "Not in NHP cohort (mental-health excluded from main NHP); capital via West Yorkshire ICB Mental Health Capital Programme"},
            {"label": "Listed-building flag", "value": "Bootham Park York is Grade-II listed (1772 Carr of York psychiatric building) — decant 2015, partial estate retained, modernisation infeasible"},
            {"label": "Forensic-secure constraint", "value": "Newsam Centre medium-secure perimeter, ligature-anchor and observation standards drive recurrent equipment + fabric refresh"},
            {"label": "Valuation cycle phase", "value": "5-yearly full revaluation 2024-25; interim VOA indexation"},
            {"label": "Delivery body", "value": "Trust Estates & Facilities + external valuer DHSC central panel"},
